<template>
  <div class="page-shell"><AppHeader /><main class="page-main"><div class="container">
    <template v-if="isManager">
      <div class="page-heading"><div><span class="eyebrow ai-eyebrow">✦ SCIKIT-LEARN DEMAND INTELLIGENCE</span><h1 class="page-title">관리자용 4주 수요예측</h1><p class="page-subtitle">그룹×자산 카테고리의 과거 요청량을 학습해 부족 가능성과 이동 대안을 계산합니다.</p></div><button class="btn btn-primary" :disabled="training" @click="train">{{ training?'학습 중...':'모델 다시 학습' }}</button></div>
      <div v-if="error" class="error-box feedback">{{ error }}</div><div v-if="message" class="success-box feedback">{{ message }}</div>
      <div v-if="loading" class="loading-state surface"><div class="spinner"></div><span>예측 결과와 모델 평가를 불러오고 있습니다.</span></div>
      <template v-else-if="forecast">
        <section class="model-strip surface"><div><small>선택 모델</small><strong>{{ modelName }}</strong><span>검증 기간의 WAPE가 가장 낮은 모델</span></div><div><small>분석 이력</small><strong>{{ evaluation?.eventCount?.toLocaleString()||'—' }}건</strong><span>{{ evaluation?.dataStart }} ~ {{ evaluation?.dataEnd }}</span></div><div><small>기준선 WAPE</small><strong>{{ pct(evaluation?.baselineWape) }}</strong><span>최근 4주 이동평균</span></div><div class="model-result"><small>AI 모델 WAPE</small><strong>{{ pct(evaluation?.modelWape) }}</strong><span>기준선 대비 {{ signed(evaluation?.improvementPercent) }}</span></div></section>
        <div class="risk-summary"><button :class="{active:riskFilter==='ALL'}" @click="riskFilter='ALL'">전체 {{ forecast.items.length }}</button><button class="risk-high" :class="{active:riskFilter==='HIGH'}" @click="riskFilter='HIGH'">부족 {{ riskCount('HIGH') }}</button><button class="risk-medium" :class="{active:riskFilter==='MEDIUM'}" @click="riskFilter='MEDIUM'">주의 {{ riskCount('MEDIUM') }}</button><button class="risk-low" :class="{active:riskFilter==='LOW'}" @click="riskFilter='LOW'">안정 {{ riskCount('LOW') }}</button></div>
        <div v-if="filteredItems.length" class="forecast-grid">
          <article v-for="item in filteredItems" :key="item.category" class="forecast-card surface"><div class="forecast-head"><div><span class="category-symbol">{{ categoryIcon(item.category) }}</span><div><small>{{ item.category }}</small><h3>{{ categoryLabel(item.category) }}</h3></div></div><span :class="['risk-pill',`risk-${item.riskLevel.toLowerCase()}`]">{{ riskLabel(item.riskLevel) }}</span></div>
            <div class="numbers"><div><small>4주 예상 요청</small><strong>{{ item.forecastDemand }}건</strong></div><div><small>필요 수량</small><strong>{{ item.requiredUnits }}개</strong></div><div><small>현재 재고</small><strong>{{ item.totalStock }}개</strong></div><div><small>부족</small><strong :class="{shortage:item.shortageUnits>0}">{{ item.shortageUnits }}개</strong></div></div>
            <div class="chart"><div v-for="week in item.weekly" :key="week.weekStart" class="bar-column"><span>{{ week.predictedDemand }}</span><div class="bar-track"><i :style="{height:barHeight(item,week)}"></i></div><small>{{ weekLabel(week.weekStart) }}</small></div></div>
            <div v-if="item.transferSuggestions.length" class="transfer"><strong>먼저 이동 검토</strong><span v-for="suggestion in item.transferSuggestions" :key="suggestion.fromGroupId">{{ groupName(suggestion.fromGroupId) }}에서 {{ suggestion.suggestedQuantity }}개</span></div><div v-else-if="item.shortageUnits>0" class="purchase"><strong>도입 검토 권장</strong><span>이동 가능한 타 그룹 잉여 재고가 없습니다.</span></div><div v-else class="stable"><strong>추가 도입 불필요</strong><span>예측 수요를 현재 재고로 감당할 수 있습니다.</span></div>
          </article>
        </div>
        <div v-else class="empty-state surface"><strong>선택한 위험 단계의 카테고리가 없습니다.</strong></div>
        <section class="method surface"><div><span>1</span><strong>데이터</strong><p>18개월의 대여 요청 이벤트를 주 단위로 집계합니다.</p></div><i>→</i><div><span>2</span><strong>시간순 분리</strong><p>미래 데이터가 학습에 섞이지 않게 학습·검증·테스트를 나눕니다.</p></div><i>→</i><div><span>3</span><strong>모델 선택</strong><p>Poisson, Random Forest, Gradient Boosting을 검증 WAPE로 비교합니다.</p></div><i>→</i><div><span>4</span><strong>업무 활용</strong><p>예상 대여기간과 재고를 결합해 이동 또는 도입을 제안합니다.</p></div></section>
      </template>
    </template>
    <div v-else class="empty-state surface"><strong>그룹 관리자만 수요예측을 볼 수 있습니다.</strong><router-link :to="`/groups/${groupId}`" class="btn btn-outline">그룹 홈</router-link></div>
  </div></main></div>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import AppHeader from '@/components/AppHeader.vue'
import { analyticsApi } from '@/api/analytics.js'
import { useAuthStore } from '@/store/auth.js'
import { categoryIcon, categoryLabel } from '@/store/course.js'
import { useGroupStore } from '@/store/group.js'
const route=useRoute(),auth=useAuthStore(),groupStore=useGroupStore(),groupId=computed(()=>Number(route.params.groupId)),group=computed(()=>groupStore.currentGroup),isManager=computed(()=>auth.isInstructor||group.value?.currentRole==='MANAGER')
const forecast=ref(null),evaluation=ref(null),loading=ref(true),training=ref(false),error=ref(''),message=ref(''),riskFilter=ref('ALL')
const filteredItems=computed(()=>forecast.value?.items?.filter(item=>riskFilter.value==='ALL'||item.riskLevel===riskFilter.value)||[]),modelName=computed(()=>({poisson_regression:'Poisson 회귀',random_forest:'Random Forest',hist_gradient_boosting:'Histogram Gradient Boosting'}[evaluation.value?.modelName||forecast.value?.modelName]||evaluation.value?.modelName||'—'))
const pct=value=>value==null?'—':`${Number(value).toFixed(1)}%`,signed=value=>value==null?'—':`${Number(value)>=0?'+':''}${Number(value).toFixed(1)}% 개선`,riskCount=risk=>forecast.value?.items?.filter(item=>item.riskLevel===risk).length||0,riskLabel=risk=>({HIGH:'부족',MEDIUM:'주의',LOW:'안정'}[risk]||risk)
const weekLabel=value=>new Intl.DateTimeFormat('ko-KR',{month:'numeric',day:'numeric'}).format(new Date(`${value}T00:00:00`)),barHeight=(item,week)=>{const max=Math.max(...item.weekly.map(row=>Number(row.predictedDemand)),1);return`${Math.max(8,Number(week.predictedDemand)/max*100)}%`},groupName=id=>groupStore.groups.find(group=>group.id===id)?.name||`그룹 #${id}`
const explain=cause=>cause.response?.data?.detail||cause.response?.data?.message||'수요예측 결과를 불러오지 못했습니다.'
async function load(){loading.value=true;error.value='';try{await groupStore.loadGroup(groupId.value);if(!isManager.value)return;const [forecastRes,evaluationRes]=await Promise.all([analyticsApi.getForecast(groupId.value),analyticsApi.getEvaluation()]);forecast.value=forecastRes.data;evaluation.value=evaluationRes.data}catch(cause){error.value=explain(cause)}finally{loading.value=false}}
async function train(){training.value=true;error.value='';message.value='';try{const res=await analyticsApi.train();message.value=`${res.data.modelName} 학습을 완료했습니다. 분석 이력 ${Number(res.data.eventCount).toLocaleString()}건을 사용했습니다.`;await load()}catch(cause){error.value=explain(cause)}finally{training.value=false}}
onMounted(load)
</script>

