i{color:#a7b4ae}@media(max-width:900px){.model-strip{grid-template-columns:repeat(2,1fr)}.forecast-grid{grid-template-columns:1fr}.method{grid-template-columns:1fr}.method>i{display:none}}@media(max-width:560px){.model-strip{grid-template-columns:1fr}.numbers{grid-template-columns:repeat(2,1fr)}}
